import numpy as np

def step(lam,r,s):
    # polynomial orthog using QR monomials scaled
    t=(lam-lam.mean())/(lam.max()-lam.min())
    Q=np.linalg.qr(r[:,None]*np.vander(t,s+1,increasing=True))[0]
    # residual direction Q_s times sign normalized at zero
    p=np.linalg.lstsq(np.vander(t,s+1,increasing=True),Q[:,-1]/r,rcond=None)[0]
    sign=np.sign(np.polynomial.polynomial.polyval(-lam.mean()/(lam.max()-lam.min()),p))
    return Q[:,-1]*sign

