 for k in range(D):c[k]=np.linalg.solve(G[0],-moms[k,s:2*s]-sum(G[j]@c[k-j] for j in range(1,k+1)))
 pp=c@Vander[:s];pp[0]+=lam**s
 ww=mul(w,mul(pp,pp));return div(ww,ww.sum(axis=1)[:,None])
def field(x):
